.sl-hero-vid-gallery {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  padding-block: clamp(3rem, 6vw, 5rem);
}
.sl-hero-vid-gallery .sl-bg-deco { z-index: 0; opacity: 0.35; }
.sl-hero-vid-gallery .sl-wave-svg { top: -10%; inset-inline-start: -5%; width: 50%; height: 50%; }
.sl-hero-vid-gallery .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-vid-gallery .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-vid-gallery .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-vid-gallery .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-vid-gallery .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-vid-gallery .sl-bg-primary {
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-vid-gallery .sl-badge-subtle,
.sl-hero-vid-gallery .sl-feature-icon {
  background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
  color: var(--smartlearn-primary);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-vid-gallery .sl-feature-icon {
  width: 56px;
  height: 56px;
}
.sl-hero-vid-gallery .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-vid-gallery .sl-btn-primary:hover,
.sl-hero-vid-gallery .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-vid-gallery .sl-btn-outline-primary {
  background-color: transparent;
  border: 2px solid var(--smartlearn-primary);
  color: var(--smartlearn-primary);
}
.sl-hero-vid-gallery .sl-btn-outline-primary:hover,
.sl-hero-vid-gallery .sl-btn-outline-primary:focus-visible {
  background-color: var(--smartlearn-btn-bg);
  border-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-vid-gallery .sl-tracking-tight { letter-spacing: -0.04em; }
.sl-hero-vid-gallery .sl-hero-headline { line-height: 1.1; }
.sl-hero-vid-gallery .sl-avatar-pill {
  width: 44px;
  height: 44px;
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
  border: 2px solid var(--smartlearn-bg);
}
.sl-hero-vid-gallery .sl-avatar-pill + .sl-avatar-pill {
  margin-inline-start: -14px;
}
.sl-hero-vid-gallery .sl-main-video-container {
  aspect-ratio: 16 / 9;
  width: 100%;
  background-color: #0f172a;
}
.sl-hero-vid-gallery .sl-scrim-overlay {
  background: linear-gradient(to right, rgba(15, 23, 42, 0.84) 0%, rgba(15, 23, 42, 0.45) 55%, rgba(15, 23, 42, 0.15) 100%);
}
[dir="rtl"] .sl-hero-vid-gallery .sl-scrim-overlay {
  background: linear-gradient(to left, rgba(15, 23, 42, 0.84) 0%, rgba(15, 23, 42, 0.45) 55%, rgba(15, 23, 42, 0.15) 100%);
}
.sl-hero-vid-gallery .sl-stage-caption {
  max-width: 78%;
}
.sl-hero-vid-gallery .sl-duration-pill {
  background-color: rgba(15, 23, 42, 0.82);
  color: #ffffff;
  font-size: 11px;
}
.sl-hero-vid-gallery .sl-play-main {
  width: 68px;
  height: 68px;
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
  border: 2px solid #ffffff;
  transition: transform 0.2s ease;
}
.sl-hero-vid-gallery .sl-nav-btn {
  top: 38%;
  width: 44px;
  height: 44px;
  z-index: 10;
  transform: translateY(-50%);
}
.sl-hero-vid-gallery .sl-nav-prev { inset-inline-start: -18px; }
.sl-hero-vid-gallery .sl-nav-next { inset-inline-end: -18px; }
.sl-hero-vid-gallery .sl-dot-btn {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background-color: color-mix(in srgb, var(--smartlearn-text-muted) 35%, transparent);
  transition: width 0.2s ease, background-color 0.2s ease;
}
.sl-hero-vid-gallery .sl-dot-btn.active {
  width: 26px;
  background-color: var(--smartlearn-primary);
}
.sl-hero-vid-gallery .sl-thumb-box {
  aspect-ratio: 16 / 9;
  border: 2px solid transparent;
}
.sl-hero-vid-gallery .sl-thumb-card.active .sl-thumb-box {
  border-color: var(--smartlearn-primary);
}
.sl-hero-vid-gallery .sl-thumb-title {
  font-size: 12px;
}
.sl-hero-vid-gallery .sl-nav-btn:focus-visible,
.sl-hero-vid-gallery .sl-play-main:focus-visible,
.sl-hero-vid-gallery .sl-dot-btn:focus-visible,
.sl-hero-vid-gallery .sl-thumb-card:focus-visible {
  outline: 2px solid var(--smartlearn-primary);
  outline-offset: 2px;
}
[dir="rtl"] .sl-hero-vid-gallery .sl-rtl-flip {
  transform: scaleX(-1);
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-vid-gallery .sl-play-main:hover { transform: scale(1.1); }
  .sl-hero-vid-gallery .sl-feature-item { transition: transform 0.25s ease; }
  .sl-hero-vid-gallery .sl-feature-item:hover { transform: translateY(-4px); }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-vid-gallery .sl-play-main,
  .sl-hero-vid-gallery .sl-dot-btn,
  .sl-hero-vid-gallery .sl-feature-item {
    transition: none;
  }
}

