(function() {
  'use strict';
  function toSafeEmbedUrl(rawUrl) {
    if (!rawUrl || typeof rawUrl !== 'string') return null;
    try {
      var u = new URL(rawUrl.trim(), window.location.origin);
      if (u.protocol !== 'https:') return null;
      if (u.hostname === 'www.youtube.com' || u.hostname === 'youtube.com' || u.hostname === 'www.youtube-nocookie.com') {
        if (u.pathname.indexOf('/embed/') === 0) {
          u.searchParams.set('autoplay', '1');
          return u.toString();
        }
      }
      if (u.hostname === 'player.vimeo.com' && u.pathname.indexOf('/video/') === 0) {
        u.searchParams.set('autoplay', '1');
        return u.toString();
      }
      return null;
    } catch (e) {
      return null;
    }
  }
  function initVideoGalleryHeroes() {
    var roots = document.querySelectorAll('.sl-hero-vid-gallery');
    if (!roots.length) return;
    roots.forEach(function(root) {
      if (root.dataset.slInit === '1') return;
      root.dataset.slInit = '1';
      var mainContainer = root.querySelector('.sl-main-video-container');
      var playBtn = root.querySelector('.sl-play-main');
      var mainImg = root.querySelector('.sl-main-video-img');
      var titleEl = root.querySelector('.sl-main-title');
      var descEl = root.querySelector('.sl-main-desc');
      var durEl = root.querySelector('.sl-main-duration');
      var embedSlot = root.querySelector('.sl-video-embed-slot');
      var thumbs = Array.prototype.slice.call(root.querySelectorAll('.sl-thumb-card'));
      var dots = Array.prototype.slice.call(root.querySelectorAll('.sl-dot-btn'));
      var prevBtn = root.querySelector('.sl-nav-prev');
      var nextBtn = root.querySelector('.sl-nav-next');
      if (!mainContainer || !playBtn || !thumbs.length) return;
      var activeIdx = 0;
      function clearEmbed() {
        if (!embedSlot) return;
        while (embedSlot.firstChild) embedSlot.removeChild(embedSlot.firstChild);
        embedSlot.classList.add('d-none');
      }
      function selectSlide(idx) {
        activeIdx = (idx + thumbs.length) % thumbs.length;
        var card = thumbs[activeIdx];
        clearEmbed();
        var thumbImg = card.querySelector('img');
        var thumbTitle = card.querySelector('.sl-thumb-title');
        var thumbDur = card.querySelector('.sl-thumb-duration');
        if (mainImg && thumbImg) mainImg.setAttribute('src', thumbImg.getAttribute('src') || '');
        if (titleEl && thumbTitle) titleEl.textContent = thumbTitle.textContent.trim();
        if (descEl) descEl.textContent = card.getAttribute('data-video-desc') || '';
        if (durEl && thumbDur) durEl.textContent = thumbDur.textContent.trim();
        playBtn.setAttribute('data-video-url', card.getAttribute('data-video-url') || '');
        thumbs.forEach(function(t, i) {
          var isOn = (i === activeIdx);
          t.classList.toggle('active', isOn);
          t.setAttribute('aria-pressed', isOn ? 'true' : 'false');
        });
        dots.forEach(function(d, i) {
          var isOn = (i === activeIdx);
          d.classList.toggle('active', isOn);
          d.setAttribute('aria-selected', isOn ? 'true' : 'false');
        });
      }
      playBtn.addEventListener('click', function(e) {
        if (root.querySelector('[data-sl-edit-id]')) return;
        e.preventDefault();
        var safeSrc = toSafeEmbedUrl(playBtn.getAttribute('data-video-url'));
        if (!safeSrc || !embedSlot) return;
        clearEmbed();
        var iframe = document.createElement('iframe');
        iframe.src = safeSrc;
        iframe.title = (titleEl ? titleEl.textContent.trim() : 'Featured video') + ' player';
        iframe.referrerPolicy = 'strict-origin-when-cross-origin';
        iframe.className = 'w-100 h-100 border-0';
        iframe.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture');
        iframe.setAttribute('allowfullscreen', 'true');
        embedSlot.appendChild(iframe);
        embedSlot.classList.remove('d-none');
      });
      thumbs.forEach(function(thumb, i) {
        thumb.addEventListener('click', function() {
          if (root.querySelector('[data-sl-edit-id]')) return;
          selectSlide(i);
        });
      });
      dots.forEach(function(dot, i) {
        dot.addEventListener('click', function() {
          selectSlide(i);
        });
      });
      if (prevBtn) prevBtn.addEventListener('click', function() { selectSlide(activeIdx - 1); });
      if (nextBtn) nextBtn.addEventListener('click', function() { selectSlide(activeIdx + 1); });
    });
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initVideoGalleryHeroes);
  } else {
    initVideoGalleryHeroes();
  }
})();
